# Implements: SPEC-411 test harness: writes the console scripts of the Ghoul screenshot suite.
# Every shot is taken in a paused frame (run with +set fixedtime 30 so that frame N is the same game
# moment in every run), once normally and once with ghl_no_render 1 (<name>_nog) for ghoulcmp.py.
import os

HERE = os.path.dirname(os.path.abspath(__file__))
HEAD = ['// SPDX-License-Identifier: GPL-2.0-or-later',
        '// Implements: SPEC-411 (black-box screenshot script, generated by gen_scripts.py)',
        '// (No semicolons in comments: the command buffer splits lines at them.)',
        'alias w10 "wait;wait;wait;wait;wait;wait;wait;wait;wait;wait"',
        'alias w100 "w10;w10;w10;w10;w10;w10;w10;w10;w10;w10"',
        'alias w40 "w10;w10;w10;w10"']


def shot(name, sets=(), unsets=()):
    out = []
    for s in sets:
        out.append('set ' + s)
    # the harness sees the OMSHOT line in the log some frames later: keep the state for 40 frames
    out += ['w10', 'echo OMSHOT ' + name, 'w40', 'set ghl_no_render 1', 'w10', 'echo OMSHOT %s_nog' % name,
            'w40', 'set ghl_no_render 0']
    for s in unsets:
        out.append('set ' + s)
    return out


DEFAULTS = ['r_fullbright 0', 'ghl_light_method 2', 'ghl_shadows 2', 'ghl_wireframe 0', 'ghl_light_multiply 1.3',
            'ghl_fast_lights 0', 'ghl_specular 1', 'ghl_max_lights 3']

VARIANTS = [
    ('lm0', ['ghl_light_method 0']),
    ('lm1', ['ghl_light_method 1']),
    ('lm3', ['ghl_light_method 3']),
    ('fast', ['ghl_fast_lights 1']),
    ('maxl8', ['ghl_max_lights 8']),
    ('fullb', ['r_fullbright 1']),
    ('mult05', ['ghl_light_multiply 0.5']),
    ('sh0', ['ghl_shadows 0']),
    ('sh1', ['ghl_shadows 1']),
    ('wire', ['ghl_wireframe 1']),
]


def intro():
    lines = HEAD + ['w100', 'map tsr1']
    done = 0
    for k, variants in [(13, False), (16, True), (19, True), (25, False), (28, False)]:
        lines += ['w100'] * (k - done)
        done = k
        lines += ['pause', 'w10']
        lines += shot('i%02d' % k)
        if variants:
            for name, sets in VARIANTS:
                lines += shot('i%02d%s' % (k, name), sets, DEFAULTS)
        lines += ['w10', 'pause']
    lines += ['w10', 'quit']
    return lines


def play():
    """tsr1 with the intro skipped: the player's room, view weapon, own shadow, firing"""
    lines = HEAD + ['w100', 'map tsr1', 'w100', 'set sv_jumpcinematic 1', 'w100', 'w100']
    lines += ['pause', 'w10']
    lines += shot('p1')
    for name, sets in VARIANTS + [('pshadow0', ['ghl_player_shadow 0'])]:
        lines += shot('p1' + name, sets, DEFAULTS + ['ghl_player_shadow 1'])
    lines += ['w10', 'pause', 'w100', '+attack', 'w10', '-attack', 'w10', 'pause', 'w10']
    lines += shot('p2')
    lines += ['w10', 'pause', 'w10', '+attack', 'w10', 'pause', 'w10']
    lines += shot('p3')
    lines += ['w10', 'pause', '-attack', 'w100', 'w100', 'pause', 'w10']
    lines += shot('p4')
    lines += ['w10', 'pause', 'w10', 'quit']
    return lines


def nyc2():
    """nyc2 start (the I4a report of a different head skin): paused every 40 frames"""
    lines = HEAD + ['set cl_subtitles 0', 'map nyc2']
    for k in range(1, 9):
        lines += ['w40', 'pause', 'w10']
        lines += shot('n%d' % k)
        lines += ['w10', 'pause']
    lines += ['w10', 'quit']
    return lines


MAPS = ['irq3b', 'trn1', 'sib1', 'kos1', 'ger1', 'jpn1', 'sud3', 'irq1a', 'kos3', 'nyc1']


def maps():
    """level starts without the intro cinematic: characters, props, fog regions; obj_fog variants"""
    lines = HEAD + ['set sv_jumpcinematic 1', 'set cl_subtitles 0']
    for m in MAPS:
        lines += ['map ' + m, 'w100', 'w100', 'w100', 'pause', 'w10']
        lines += shot(m)
        lines += shot(m + 'objfog0', ['ghl_obj_fog 0'], ['ghl_obj_fog 1'])
        lines += ['w10', 'pause', 'w10']
    lines += ['quit']
    return lines


def write(name, lines):
    with open(os.path.join(HERE, name), 'w', newline='\n') as f:
        f.write('\n'.join(lines) + '\n')


if __name__ == '__main__':
    write('suite_intro.cfg', intro())
    write('suite_play.cfg', play())
    write('suite_nyc2.cfg', nyc2())
    write('suite_maps.cfg', maps())
